MATCH (e:PlantItem {tag: 'R-5301'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-28006'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (u:PlantItem:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'V-2601'})
RETURN DISTINCT u.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'K-5401'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-4502'})-[:is_drawn_on]->(sheet:Sheet)
RETURN sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'P-4902C'})-[:measured_by]->(instrument:PlantItem)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE EXISTS {
  (sensor)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'LIC-32056'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

MATCH (e:PlantItem {tag: 'EA-1901'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem)<-[:send_signal_to*]-(c:ProcessControlFunction)
RETURN DISTINCT c.loop_tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-3001A'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-901B'}), (b:PlantItem {tag: 'V-901'})
RETURN a.tag AS tag1, b.tag AS tag2, a.unit_id = b.unit_id AS same_unit
}

MATCH (loop:ProcessControlFunction {loop_tag: 'TIC-32019'})-[:send_signal_to*1..]->(actuator:ActuatingFunction)-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-802C'})-[:measured_by]->(instrument:PlantItem)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem {loop_tag: 'TI-6060'})
RETURN equipment.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1601'}), (b:PlantItem {tag: 'F-1701A'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'GTV-17001' AND y.tag <> 'GTV-17001')+ (b)
} AS reachable

MATCH (a:PlantItem {tag: 'E-5502'}), (b:PlantItem {tag: 'D-5501'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count, collect(DISTINCT v.tag) AS tags

MATCH (source:PlantItem {tag: 'P-2401'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-54007'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'EA-5301'})-[:line_to]-(v:Valve)<-[:control]-(act:PlantItem {kind: 'actuator'})<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'M-601'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1301'}), (b:PlantItem {tag: 'F-1801A'}), (c:PlantItem {tag: 'CHV-13002'})
RETURN a.tag AS source, b.tag AS target, c.tag AS excluded_valve,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x <> c AND y <> c)+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'P-3701A'}), (b:PlantItem {tag: 'TK-3803'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (i:PlantItem {tag: 'EA-1901'})-[:is_drawn_on]->(s:Sheet)
RETURN i.tag AS tag, s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (loop:ProcessControlFunction {loop_tag: 'PIC-36030'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1502'}), (b:PlantItem {tag: 'TK-1601'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:Valve)-[:line_to*1..]->(e:Equipment {tag: 'EA-5301'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(:PlantItem {tag: 'EA-3401'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-1601'}), (b:PlantItem {tag: 'F-1801A'})
WHERE EXISTS {
  MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem) WHERE n.tag <> 'F-1701A' AND m.tag <> 'F-1701A')* (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag
LIMIT 1

MATCH (a:PlantItem {tag: 'F-4001'}), (b:PlantItem {tag: 'K-4201'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-5302'}), (b:PlantItem {tag: 'EA-5901'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'CHV-55005' AND y.tag <> 'CHV-55005')+ (b)
       } AS reachable

MATCH (s:PlantItem {tag: 'V-5301'}), (e:PlantItem {tag: 'EA-5901'}), (v:Valve)
WHERE EXISTS { (s)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag kouka

MATCH (s:PlantItem {tag: 'V-5301'}), (e:PlantItem {tag: 'EA-5901'}), (v:Valve)
WHERE EXISTS { (s)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'E-1901'}), (b:PlantItem {tag: 'V-3001'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'E-2503' AND y.tag <> 'E-2503')+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'E-1901'}), (b:PlantItem {tag: 'V-3001'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'E-2503' AND y.tag <> 'E-2503')+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'P-301B'}), (b:PlantItem {tag: 'D-2701'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-3202B'}), (b:PlantItem {tag: 'EA-5901'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-4301'}),
      (b:PlantItem {tag: 'D-4301'}),
      (excluded:PlantItem {tag: 'EA-4301'})
RETURN EXISTS {
  MATCH (a)-[:line_to*1..]->(b)
  WHERE NOT EXISTS {
    MATCH (a)-[:line_to*1..]->(excluded)-[:line_to*1..]->(b)
  }
} AS can_flow_without_EA

MATCH (:PlantItem {tag: 'T-3601'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem {loop_tag: 'LIC-32056'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem {loop_tag: 'LI-50022'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (target:PlantItem {tag: 'K-5401'})
MATCH (v:Valve)-[:line_to*1..]->(target)
WHERE NOT EXISTS {
  MATCH (v)-[:line_to*1..]->(downstream:Valve)-[:line_to*1..]->(target)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'V-4801'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;
